schema_ddl:
CREATE TYPE stato_ordine AS ENUM ('pianificato', 'in_corso', 'sospeso', 'completato', 'annullato');

CREATE TYPE priorita_ordine AS ENUM ('bassa', 'normale', 'urgente');

CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ragione_sociale TEXT NOT NULL,
    partita_iva TEXT NOT NULL UNIQUE,
    citta TEXT NOT NULL
);

CREATE TABLE articoli (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_articolo TEXT NOT NULL UNIQUE,
    descrizione TEXT NOT NULL,
    unita_misura TEXT NOT NULL
);

CREATE TABLE dipendenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    matricola TEXT NOT NULL UNIQUE,
    reparto TEXT NOT NULL
);

CREATE TABLE linee_produzione (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_linea TEXT NOT NULL UNIQUE,
    nome_linea TEXT NOT NULL,
    capacita_giornaliera INT NOT NULL CHECK (capacita_giornaliera > 0)
);

CREATE TABLE ordini_produzione (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    articolo_id INT NOT NULL REFERENCES articoli(id),
    responsabile_id INT REFERENCES dipendenti(id),
    linea_id INT REFERENCES linee_produzione(id),
    stato_ordine stato_ordine NOT NULL DEFAULT 'pianificato',
    priorita priorita_ordine NOT NULL DEFAULT 'normale',
    quantita_richiesta INT NOT NULL CHECK (quantita_richiesta > 0),
    data_avvio DATE,
    data_consegna DATE,
    CHECK (data_consegna IS NULL OR data_avvio IS NULL OR data_consegna >= data_avvio)
);
